    cMensaje    VARCHAR2(500);
    cIdTipoSeg  COTIZACIONES.IdTipoSeg%TYPE;
    cPlanCob    COTIZACIONES.PlanCob%TYPE;
BEGIN
    -- Validar parámetros obligatorios
    IF :nCodCia IS NULL THEN
       cMensaje := ''Debe indicar un Código de Compañía'';
    ELSIF :nCodEmpresa IS NULL THEN
       cMensaje := ''Debe indicar un Código de Empresa'';
    ELSIF :nIdCotizacion IS NULL THEN
       cMensaje := ''Debe indicar el Id. de la Cotización'';
    ELSIF :cIndAsegModelo IS NULL THEN
       cMensaje := ''Debe indicar si utiliza Asegurado Modelo la Cotización a recalcular'';
    ELSIF :cIndCensoSubgrupo IS NULL THEN
       cMensaje := ''Debe indicar si utiliza Censo por Edades la Cotización a recalcular'';
    ELSIF :cIndListadoAseg IS NULL THEN
       cMensaje := ''Debe indicar si utiliza Listado de Asegurados la Cotización a recalcular'';
    END IF;
    --
    BEGIN
       SELECT IdTipoSeg , PlanCob
       INTO   cIdTipoSeg, cPlanCob
    ' || '   FROM   COTIZACIONES
       WHERE  CodCia       = :nCodCia
         AND  CodEmpresa   = :nCodEmpresa
         AND  IdCotizacion = :nIdCotizacion;
    EXCEPTION
    WHEN NO_DATA_FOUND THEN
         cMensaje := ''No existe ese Id. de Cotización, favor de validar'';
    END;
