        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "'' || cMensaje || ''",
                    "data": {}
                }'');
        RETURN;
    END IF;
    -- Ejecutar el servicio de recalculo de primas de la cotización
    THONAPI.GENERALES_PLATAFORMA_DIGITAL.RECALCULAR_COTIZACION( p_nCodCia           => :nCodCia
                                                              , p_nCodEmpresa       => :nCodEmpresa
                                                              , p_nIdCotizacion     => :nIdCotizacion
               ' || '                                               , p_cIdTipoSeg        => cIdTipoSeg
                                                              , p_cPlanCob          => cPlanCob
                                                              , p_cIndAsegModelo    => :cIndAsegModelo
                                                              , p_cIndCensoSubgrupo => :cIndCensoSubgrupo
                                                              , p_cIndListadoAseg   => :cIndListadoAseg );
    cResultado := ''OK'';
    -- Configurar el encabezado para JSON
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;
    -- Responder en formato JSON con control de nulos
    HTP.PRN(''{
        "success": true,
        "mensaje": "Cotización recalculada correctamente.",
        "data": { "IdCotizacion": '' || NVL(TO_CHAR(:nIdCotizacion), ''NULL'') || '',
                  "cResultado": '' || NVL(TO_CHAR(cResultado), ''NULL'') || '' }
    }'');
    --      ' || '          
    COMMIT;
EXCEPTION
WHEN OTHERS THEN
