'DECLARE
    cResultado        CLOB;
    cResultado_texto  VARCHAR2(32767);
    nIncrementar      INTEGER := 4000;
    nPosicion         INTEGER := 1;
    cBuffer           VARCHAR2(4000);
    cMensaje          VARCHAR2(500);
BEGIN
    -- Validar parámetros obligatorios
    IF :nCodCia IS NULL THEN
        cMensaje := ''Debe indicar un Código de Compañía'';
    ELSIF :nCodEmpresa IS NULL THEN
        cMensaje := ''Debe indicar un Código de Empresa'';
    ELSIF :nIdCotizacion IS NULL THEN
        cMensaje := ''Debe indicar el Id. de la Cotización'';
    END IF;
    --
    IF cMensaje IS NOT NULL THEN
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "'' || cMensaje || ''",
                    "data": {}
                }'');
        RETURN;
    END IF;
    --
    cResultado := THONAPI.FLUJO_COTIZACION_SIGO.CONSULTAR_COBERTURAS( nCodCia => :' || 'nCodCia
                                                                    , nCodEmpresa => :nCodEmpresa
                                                                    , nIdCotizacion => :nIdCotizacion
                                                                    , nIDetCotizacion => :nIDetCotizacion );
    --
    BEGIN
        cResultado_texto := DBMS_LOB.SUBSTR(cResultado, 32767, 1); 
    EXCEPTION
    WHEN OTHERS THEN
        cResultado_texto := '''';
    END;
    --
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;
    --
    IF cResultado_texto IS NULL OR LENGTH(TRIM(cResultado_texto)) < 10 THEN
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "No se encontraron coberturas con los parámetros indicados",
                    "data": []
                }'');
    ELSE
         HTP.PRN(''{
                   "success": true,
                   "mensaje": "",
                  ' || ' "data": '');
        cResultado := NVL(cResultado, ''{}'');
        LOOP
            BEGIN
                DBMS_LOB.READ( cResultado, nIncrementar, nPosicion, cbuffer );
                nPosicion := nPosicion + nIncrementar;
                HTP.PRN(cbuffer);
            EXCEPTION
            WHEN NO_DATA_FOUND THEN
                EXIT;
            END;
        END LOOP;
        --
        HTP.PRN(''}'');
    END IF;
EXCEPTION
WHEN OTHERS THEN
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "'' || SQLERRM || ''",
                    "data": []
                }'');
END;');

