  ORDS.DEFINE_HANDLER(
      p_module_name    => 'cotizaciones_SIGO',
      p_pattern        => 'actualizar_detalle',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => NULL,
      p_source         => 
'DECLARE
    nRowAffect  NUMBER;
    cMensaje    VARCHAR2(500);
    nExiste     NUMBER;
BEGIN
    -- Validar parámetros obligatorios
    IF :nCodCia IS NULL THEN
       cMensaje := ''Debe indicar un Código de Compañía'';
    ELSIF :nCodEmpresa IS NULL THEN
       cMensaje := ''Debe indicar un Código de Empresa'';
    ELSIF :nIdCotizacion IS NULL THEN
       cMensaje := ''Debe indicar el Id. de la Cotización'';
    ELSIF :nIDetCotizacion IS NULL THEN
       cMensaje := ''Debe indicar el Id. del Detalle de la Cotización'';
    END IF;
    --
    SELECT COUNT(*)
    INTO   nExiste
    FROM   COTIZACIONES_DETALLE
    WHERE  CodCia         = :nCodCia
      AND  CodEmpresa     = :nCodEmpresa
      AND  IDetCotizacion = :nIDetCotizacion
      AND  IdCotizacion   = :nIdCotizacion;
    --
    IF nExiste = 0 THEN
       cMensaje := ''No existe esa Cotización/Subgrupo, favor de validar'';
    END IF;
    --
    IF cMensaje IS NOT NULL THEN
        OWA_UTIL.MIME_HEADER(''applicati' || 'on/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "'' || cMensaje || ''",
                    "data": {}
                }'');
        RETURN;
    END IF;
    -- Ejecutar el servicio de actualización de información de la cotización
    THONAPI.FLUJO_COTIZACION_SIGO.ACTUALIZAR_DETALLE( :nCodCia
                                                    , :nCodEmpresa
                                                    , :nIdCotizacion
                                                    , :nIDetCotizacion
                                                    , :cDescSubgrupo
                                                    , :nEdadLimite
                                                    , :nCantAsegurados
                                                    , :nSalarioMensual
                                                    , :nVecesSalario
                                           ' || '         , :nPorcExtraPrimaDet
                                                    , :nMontoExtraPrimaDet
                                                    , :nPrimaAsegurado
                                                    , :nSumaAsegDetLocal
                                                    , :nSumaAsegDetMoneda
                                                    , :nPrimaDetLocal
                                                    , :nPrimaDetMoneda
                                                    , :cRiesgoTarifa
                                                    , :nHorasVig
                                                    , :nDiasVig
                                                    , :nFactorAjuste
                                                    , :nFactFormulaDeduc
                                                    , :cIndEdadPromedio
                                                    , :cIndCuotaPromedio
                                    ' || '                , :cIndPrimaPromedio
                                                    , :cPrimaNetaPor );
    -- Configurar el encabezado para JSON
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;
    -- Responder en formato JSON con control de nulos
    HTP.PRN(''{
        "success": true,
        "mensaje": "Información actualizada correctamente.",
        "data": { "IdCotizacion": '' || NVL(TO_CHAR(:nIdCotizacion), ''NULL'') || '',
                  "IDetCotizacion": '' || NVL(TO_CHAR(:nIDetCotizacion), ''NULL'') || '',
                  "RegsAfectados": '' || NVL(TO_CHAR(nExiste), ''NULL'') || '' }
    }'');
    --                
    COMMIT;
EXCEPTION
WHEN OTHERS THEN
    ROLLBACK;
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;
    HTP.PRN(''{
                "success": false,
                "mensaje": "'' || SQLERRM || ''",
                "data": []
            }'');
END;');

  ORDS.DEFINE_TEMPLATE(
      p_module_name    => 'cotizaciones_SIGO',
      p_pattern        => 'copiar_cotizacion',
      p_priority       => 0,
      p_etag_type      => 'HASH',
      p_etag_query     => NULL,
      p_comments       => NULL);

  ORDS.DEFINE_HANDLER(
      p_module_name    => 'cotizaciones_SIGO',
      p_pattern        => 'copiar_cotizacion',
      p_method         => 'POST',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => 'application/json',
      p_comments       => NULL,
      p_source         => 
'DECLARE
    nIdCotizacionNew  COTIZACIONES.IdCotizacion%TYPE;
    cMensaje          VARCHAR2(500);
BEGIN
    -- Validar parámetros obligatorios
    IF :nCodCia IS NULL THEN
       cMensaje := ''Debe indicar un Código de Compañía'';
    ELSIF :nCodEmpresa IS NULL THEN
       cMensaje := ''Debe indicar un Código de Empresa'';
    ELSIF :nIdCotizacion IS NULL THEN
       cMensaje := ''Debe indicar el Id. de la Cotización'';
    ELSIF :nCodAgente IS NULL THEN
       cMensaje := ''Debe indicar la Clave del Agente para la nueva Cotización'';
    END IF;
    --
    IF cMensaje IS NOT NULL THEN
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "'' || cMensaje || ''",
                    "data": {}
                }'');
        RETURN;
    END IF;
    -- Ejecutar el servicio de copiado de cotización
    nIdCotizacionNew := THONAPI.GENERALES_PLATAFORMA' || '_DIGITAL.COPIA_COTIZACION( nCodCia => :nCodCia
                                                                             , nCodEmpresa => :nCodEmpresa
                                                                             , nIdCotizacion => :nIdCotizacion );
    --Valida si la nueva cotización es igual a 0, de ser así hubo un error en el copiado                                                    
    IF nIdCotizacionNew <= 0 THEN
        OWA_UTIL.MIME_HEADER(''application/json'', FALSE);
        OWA_UTIL.HTTP_HEADER_CLOSE;
        HTP.PRN(''{
                    "success": false,
                    "mensaje": "No se pudo copiar la cotización: '' || NVL(TO_CHAR(:nIdCotizacion), ''NULL'') || ''",
                    "data": {}
                }'');
        RETURN;
    ELSE
        --Actualiza el código del agente en la nueva cotización y la marca como cotización Web
        THONAPI.FLUJO_COTIZACION_SIGO.ACTUALIZAR_AGENTE( nCodCia => :nCodCia
                            ' || '                           , nCodEmpresa => :nCodEmpresa
                                                       , nIdCotizacion => nIdCotizacionNew
                                                       , nCodAgente => :nCodAgente );
    END IF;
    -- Configurar el encabezado para JSON
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;
    -- Responder en formato JSON con control de nulos
    HTP.PRN(''{
        "success": true,
        "mensaje": "Cotización copiada correctamente.",
        "data": { "IdCotizacion": '' || NVL(TO_CHAR(:nIdCotizacion), ''NULL'') || '',
                  "IdCotizacionNew": '' || NVL(TO_CHAR(nIdCotizacionNew), ''NULL'') || '' }
    }'');
    --                
    COMMIT;
EXCEPTION
WHEN OTHERS THEN
    ROLLBACK;
    OWA_UTIL.MIME_HEADER(''application/json'', FALSE);    
    OWA_UTIL.HTTP_HEADER_CLOSE;
    HTP.PRN(''{
                "success": false,
                "mensaje": "'' || SQLERRM || ''",
        ' || '        "data": []
            }'');
END;');

